typedef unsigned long uint64;
typedef float rational_t;
typedef float time_value_t;
class ai_interface;
class ai_action;
class chunk_file;
class stringx;

class pstring {
  uint64 pchunk[4];
  void pack_string(const char *);
public:
  pstring(const char *s) { pack_string(s); }
  pstring(const pstring& b) { for (unsigned i=0; i<4; ++i) pchunk[i]=b.pchunk[i]; }
  bool operator!=(const pstring& b) const { for(unsigned i=0;i<4;++i) if(pchunk[i]!=b.pchunk[i]) return true; return false; }
};

template<class T> class vector {
  T* start_; T* finish_; T* end_;
public:
  typedef T* iterator;
  unsigned int size() const { return finish_-start_; }
  iterator begin() { return start_; }
  iterator end() { return finish_; }
  void reserve(unsigned int);
  void push_back(const T&);
};

template<class T> class list { void* p[2]; };

class ai_goal {
protected:
  ai_interface* owner;
  rational_t priority;
  rational_t priority_modifier;
  bool in_service;
  list<ai_action*> actions;
  pstring type;
  virtual rational_t frame_advance(time_value_t);
  virtual ai_goal* make_copy(ai_interface*)=0;
  virtual void dump_actions();
  virtual void dump_action(ai_action*);
  void read_data(chunk_file&);
  virtual void handle_chunk(chunk_file&, stringx&);
public:
  ai_goal(ai_interface*);
  virtual ~ai_goal();
  virtual rational_t calculate_priority(time_value_t)=0;
  virtual void going_into_service();
  virtual void going_out_of_service();
  virtual unsigned int add_action(ai_action*);
  virtual bool running_action(unsigned int);
  virtual void dump_action(unsigned int);
  pstring get_type() const { return type; }
};

class ai_locomotion {
public:
  virtual ai_locomotion* make_copy(ai_interface*);
};

class ai_interface {
  void* vptr;
  void* my_entity;
  unsigned int flags;
  unsigned int team;
  unsigned int enemy_team;
  ai_locomotion* locomotion;
  vector<ai_goal*> goals;
  ai_goal* current_goal;
  void* target;
  rational_t help_timer;
  int disable_count;
  bool is_flagged(unsigned int f) const { return (flags & f) != 0; }
  void set_flag(unsigned int f, bool val=true) { if(val) flags|=f; else flags&=~f; }
public:
  void copy(ai_interface*);
  bool cosmetic() const { return is_flagged(0x80); }
  void set_cosmetic(bool a) { set_flag(0x80,a); }
  bool detector() const { return is_flagged(0x00100000); }
  void set_detector(bool a) { set_flag(0x00100000,a); }
};

void ai_interface::copy(ai_interface *b)
{
  goals.reserve(b->goals.size());

  vector<ai_goal *>::iterator g = b->goals.begin();
  while(g != b->goals.end())
  {
    static pstring disable_goal("DISABLE");
    if((*g)->get_type() != disable_goal)
      goals.push_back((*g)->make_copy(this));
    ++g;
  }

  if(b->locomotion)
    locomotion = b->locomotion->make_copy(this);

  set_cosmetic(b->cosmetic());
  set_detector(b->detector());
}
